import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { Amplify } from 'aws-amplify'
import outputs from '../amplify_outputs.json'
import './index.css'
import App from './App.tsx'

// Configure Amplify from the deployed backend outputs so the frontend auth state
// stays synchronized with Cognito (AUTH-05). amplify_outputs.json is generated by
// `ampx sandbox` and is gitignored — never committed.
Amplify.configure(outputs)

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
)
